package com.srent.admin;
import com.srent.audit.*;import com.srent.booking.*;import com.srent.common.ApiException;import com.srent.contract.*;import com.srent.dispute.*;import com.srent.ekyc.*;import com.srent.media.*;import com.srent.payment.*;import com.srent.room.*;import com.srent.security.CurrentUser;import com.srent.storage.StorageService;import com.srent.user.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/admin") @RequiredArgsConstructor
public class AdminController {
private final UserRepository users;private final RoomRepository rooms;private final RoomVideoRepository videos;private final BookingRepository bookings;private final PaymentRepository payments;private final LandlordVerificationRepository verifications;private final VerificationDocumentRepository verificationDocs;private final ContractAnalysisRepository analyses;private final ContractRiskItemRepository risks;private final ContractRepository contracts;private final DisputeRepository disputes;private final AuditLogRepository auditLogs;private final AuditService audit;private final StorageService storage;
public record UserResponse(UUID id,String email,String fullName,User.Role role,User.Status status,Instant createdAt){static UserResponse from(User u){return new UserResponse(u.getId(),u.getEmail(),u.getFullName(),u.getRole(),u.getStatus(),u.getCreatedAt());}}public record StatusRequest(@NotNull User.Status status){}public record ReviewRequest(@NotNull Decision decision,@Size(max=2000)String note){}public enum Decision{APPROVE,REJECT}public record Dashboard(long users,long students,long landlords,long rooms,long bookings,long pendingVerifications,long pendingVideos,long pendingContractAnalyses,long openDisputes){}public record RoomReview(UUID id,Room.ApprovalStatus approvalStatus,String rejectionReason){}public record VideoReview(UUID id,RoomVideo.Status status,String reviewNote){}public record VerificationResponse(UUID id,UUID landlordId,String legalName,String identityNumberMasked,LandlordVerification.Status status,String provider,boolean simulated,String anomalies,String adminNote,List<DocumentLink>documents){}public record DocumentLink(String type,String downloadUrl){}public record AnalysisReview(UUID contractId,ContractAnalysis.ReviewStatus reviewStatus,String provider,boolean simulated,String disclaimer,String adminNote){}
@GetMapping("/users")public Page<UserResponse> userList(@RequestParam(required=false)User.Role role,@PageableDefault(size=30,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return(role==null?users.findAll(p):users.findAllByRole(role,p)).map(UserResponse::from);}
@PatchMapping("/users/{id}/status")@Transactional public UserResponse status(@PathVariable UUID id,@Valid@RequestBody StatusRequest q){var u=users.findById(id).orElseThrow(()->ApiException.notFound("Người dùng"));if(u.getId().equals(CurrentUser.id())&&q.status()==User.Status.LOCKED)throw ApiException.badRequest("CANNOT_LOCK_SELF","Admin không thể tự khóa mình");u.setStatus(q.status());audit.log(CurrentUser.id(),"USER_STATUS_CHANGED","USER",id,"status="+q.status());return UserResponse.from(u);}
@PatchMapping("/rooms/{id}/review")@Transactional public RoomReview room(@PathVariable UUID id,@Valid@RequestBody ReviewRequest q){var r=rooms.findById(id).orElseThrow(()->ApiException.notFound("Phòng"));if(r.getApprovalStatus()!=Room.ApprovalStatus.PENDING)throw ApiException.conflict("INVALID_ROOM_STATE","Phòng không ở trạng thái PENDING");r.setApprovalStatus(q.decision()==Decision.APPROVE?Room.ApprovalStatus.APPROVED:Room.ApprovalStatus.REJECTED);r.setRejectionReason(q.decision()==Decision.REJECT?q.note():null);audit.log(CurrentUser.id(),"ROOM_REVIEWED","ROOM",id,"decision="+q.decision());return new RoomReview(id,r.getApprovalStatus(),r.getRejectionReason());}
@GetMapping("/rooms")public Page<RoomController.Response> roomQueue(@PageableDefault(size=20,sort="createdAt")Pageable p){return rooms.findAllByApprovalStatus(Room.ApprovalStatus.PENDING,p).map(RoomController.Response::from);}
@PatchMapping("/videos/{id}/review")@Transactional public VideoReview video(@PathVariable UUID id,@Valid@RequestBody ReviewRequest q){var v=videos.findById(id).orElseThrow(()->ApiException.notFound("Video"));if(v.getStatus()!=RoomVideo.Status.PENDING)throw ApiException.conflict("INVALID_VIDEO_STATE","Video không ở trạng thái PENDING");v.setStatus(q.decision()==Decision.APPROVE?RoomVideo.Status.APPROVED:RoomVideo.Status.REJECTED);v.setReviewNote(q.note());audit.log(CurrentUser.id(),"VIDEO_REVIEWED","ROOM_VIDEO",id,"decision="+q.decision());return new VideoReview(id,v.getStatus(),v.getReviewNote());}
public record VideoQueueItem(UUID id,UUID roomId,String roomTitle,RoomVideo.Status status,String videoUrl,Long sizeBytes,java.math.BigDecimal distanceMeters,java.math.BigDecimal gpsAccuracyMeters,Instant capturedAt){}
@GetMapping("/videos")@Transactional(readOnly=true)public Page<VideoQueueItem> videoQueue(@PageableDefault(size=20,sort="createdAt")Pageable p){return videos.findAllByStatus(RoomVideo.Status.PENDING,p).map(v->new VideoQueueItem(v.getId(),v.getRoom().getId(),v.getRoom().getTitle(),v.getStatus(),storage.publicUrl(v.getObjectKey()),v.getSizeBytes(),v.getDistanceMeters(),v.getGpsAccuracyMeters(),v.getCapturedAt()));}
@GetMapping("/verifications")@Transactional(readOnly=true)public Page<VerificationResponse> verificationList(@PageableDefault(size=20,sort="createdAt")Pageable p){return verifications.findAllByStatusIn(List.of(LandlordVerification.Status.SUBMITTED,LandlordVerification.Status.AI_PROCESSED,LandlordVerification.Status.NEEDS_REVIEW),p).map(this::verificationResponse);}
@PatchMapping("/verifications/{id}/review")@Transactional public VerificationResponse verification(@PathVariable UUID id,@Valid@RequestBody ReviewRequest q){var v=verifications.findById(id).orElseThrow(()->ApiException.notFound("Hồ sơ xác minh"));if(v.getStatus()==LandlordVerification.Status.APPROVED||v.getStatus()==LandlordVerification.Status.REJECTED)throw ApiException.conflict("VERIFICATION_ALREADY_REVIEWED","Hồ sơ đã được duyệt");v.setStatus(q.decision()==Decision.APPROVE?LandlordVerification.Status.APPROVED:LandlordVerification.Status.REJECTED);v.setAdminNote(q.note());audit.log(CurrentUser.id(),"VERIFICATION_REVIEWED","LANDLORD_VERIFICATION",id,"decision="+q.decision());return verificationResponse(v);}
@GetMapping("/contracts")@Transactional(readOnly=true)public List<AnalysisReview> contractQueue(){return analyses.findAll().stream().filter(a->a.getReviewStatus()==ContractAnalysis.ReviewStatus.PENDING).map(this::analysisReview).toList();}
@PatchMapping("/contracts/{contractId}/review")@Transactional public AnalysisReview contract(@PathVariable UUID contractId,@Valid@RequestBody ReviewRequest q){var a=analyses.findByContractId(contractId).orElseThrow(()->ApiException.notFound("Phân tích hợp đồng"));if(a.getReviewStatus()!=ContractAnalysis.ReviewStatus.PENDING)throw ApiException.conflict("ANALYSIS_ALREADY_REVIEWED","Phân tích đã được duyệt");a.setReviewStatus(q.decision()==Decision.APPROVE?ContractAnalysis.ReviewStatus.PUBLISHED:ContractAnalysis.ReviewStatus.REJECTED);a.setAdminNote(q.note());a.getContract().setStatus(q.decision()==Decision.APPROVE?Contract.Status.PUBLISHED:Contract.Status.REJECTED);audit.log(CurrentUser.id(),"CONTRACT_ANALYSIS_REVIEWED","CONTRACT",contractId,"decision="+q.decision());return analysisReview(a);}
@GetMapping("/disputes")public Page<DisputeController.Response> disputeQueue(@PageableDefault(size=20,sort="createdAt")Pageable p){return disputes.findAllByStatusIn(List.of(Dispute.Status.OPEN,Dispute.Status.IN_REVIEW),p).map(DisputeController.Response::from);}
@PatchMapping("/disputes/{id}/review")@Transactional public DisputeController.Response dispute(@PathVariable UUID id,@RequestBody @Valid DisputeReview q){var d=disputes.findById(id).orElseThrow(()->ApiException.notFound("Khiếu nại"));d.setStatus(q.status());d.setAdminNote(q.note());audit.log(CurrentUser.id(),"DISPUTE_REVIEWED","DISPUTE",id,"status="+q.status()+"; no automatic transfer or AI ruling");return DisputeController.Response.from(d);}public record DisputeReview(@NotNull Dispute.Status status,@Size(max=3000)String note){}
@GetMapping("/dashboard")public Dashboard dashboard(){return new Dashboard(users.count(),users.countByRole(User.Role.STUDENT),users.countByRole(User.Role.LANDLORD),rooms.count(),bookings.count(),verifications.countByStatusIn(List.of(LandlordVerification.Status.SUBMITTED,LandlordVerification.Status.AI_PROCESSED,LandlordVerification.Status.NEEDS_REVIEW)),videos.countByStatus(RoomVideo.Status.PENDING),analyses.countByReviewStatus(ContractAnalysis.ReviewStatus.PENDING),disputes.countByStatusIn(List.of(Dispute.Status.OPEN,Dispute.Status.IN_REVIEW)));}
@GetMapping("/transactions")public Page<PaymentController.Response> transactions(@PageableDefault(size=30)Pageable p){return payments.findAllByOrderByCreatedAtDesc(p).map(PaymentController.Response::from);}
@GetMapping("/audit-logs")public Page<AuditRecord> logs(@PageableDefault(size=50)Pageable p){return auditLogs.findAllByOrderByCreatedAtDesc(p).map(x->new AuditRecord(x.getId(),x.getActorId(),x.getAction(),x.getResourceType(),x.getResourceId(),x.getDetails(),x.getCreatedAt()));}public record AuditRecord(UUID id,UUID actorId,String action,String resourceType,UUID resourceId,String details,Instant createdAt){}
private VerificationResponse verificationResponse(LandlordVerification v){return new VerificationResponse(v.getId(),v.getLandlord().getId(),v.getLegalName(),v.getIdentityNumberMasked(),v.getStatus(),v.getProvider(),v.isSimulated(),v.getAnomalyReasons(),v.getAdminNote(),verificationDocs.findAllByVerificationId(v.getId()).stream().map(d->new DocumentLink(d.getDocumentType(),storage.presignedDownload(d.getObjectKey()))).toList());}private AnalysisReview analysisReview(ContractAnalysis a){return new AnalysisReview(a.getContract().getId(),a.getReviewStatus(),a.getProvider(),a.isSimulated(),a.getDisclaimer(),a.getAdminNote());}
}
